package com.healthcare.security;
import com.healthcare.service.CustomUserDetailsService;import jakarta.servlet.*;import jakarta.servlet.http.*;import lombok.RequiredArgsConstructor;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;
@Component @RequiredArgsConstructor public class JwtAuthFilter extends OncePerRequestFilter { private final JwtService jwtService; private final CustomUserDetailsService uds;
@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain) throws ServletException,IOException{ String h=req.getHeader("Authorization"); if(h!=null && h.startsWith("Bearer ")){ String t=h.substring(7); if(jwtService.isValid(t)&&SecurityContextHolder.getContext().getAuthentication()==null){ var user=uds.loadUserByUsername(jwtService.extractUsername(t)); var auth=new UsernamePasswordAuthenticationToken(user,null,user.getAuthorities()); auth.setDetails(new WebAuthenticationDetailsSource().buildDetails(req)); SecurityContextHolder.getContext().setAuthentication(auth);} } chain.doFilter(req,res);} }
